-- Question 1: Store Location
-- Goal: Display each store's ID, city, and country.
-- Tables needed: store, address, city, country.
-- Relationship path:
-- store -> address -> city -> country

SELECT
    store.store_id AS store_id,
    city.city AS city,
    country.country AS country
FROM store
JOIN address
    ON store.address_id = address.address_id
JOIN city
    ON address.city_id = city.city_id
JOIN country
    ON city.country_id = country.country_id;

	
	-- Question 2: Revenue by Store
-- Goal: Calculate the total revenue generated by each store.
-- Tables needed: store, staff, payment.
-- Relationship path:
-- store -> staff -> payment

SELECT
    store.store_id AS store_id,
    ROUND(SUM(payment.amount), 2) AS total_revenue
FROM store
JOIN staff
    ON store.store_id = staff.store_id
JOIN payment
    ON staff.staff_id = payment.staff_id
GROUP BY
    store.store_id
ORDER BY
    total_revenue DESC;
	
	-- Question 3: Average Film Length by Category
-- Goal: Calculate the average running time of films in each category.
-- Tables needed: film, film_category, category.
-- Relationship path:
-- film -> film_category -> category

SELECT
    category.name AS category,
    ROUND(AVG(film.length), 2) AS average_length
FROM film
JOIN film_category
    ON film.film_id = film_category.film_id
JOIN category
    ON film_category.category_id = category.category_id
GROUP BY
    category.name;
	
	-- Question 4: Longest Film Categories
-- Goal: Rank film categories by their average running time, from longest to shortest.
-- Tables needed: film, film_category, category.
-- Relationship path:
-- film -> film_category -> category

SELECT
    category.name AS category,
    ROUND(AVG(film.length), 2) AS average_length
FROM film
JOIN film_category
    ON film.film_id = film_category.film_id
JOIN category
    ON film_category.category_id = category.category_id
GROUP BY
    category.name
ORDER BY
    average_length DESC;
	
	-- Question 5: Most Frequently Rented Movies
-- Goal: Rank movies by how many times they were rented.
-- Tables needed: film, inventory, rental.
-- Relationship path:
-- film -> inventory -> rental

SELECT
    film.title AS title,
    COUNT(rental.rental_id) AS rental_count
FROM film
JOIN inventory
    ON film.film_id = inventory.film_id
JOIN rental
    ON inventory.inventory_id = rental.inventory_id
GROUP BY
    film.film_id,
    film.title
ORDER BY
    rental_count DESC;
	
	-- Question 6: Top Five Genres by Gross Revenue
-- Goal: Rank the five film genres that generated the highest total revenue.
-- Tables needed: category, film_category, inventory, rental, payment.
-- Relationship path:
-- category -> film_category -> inventory -> rental -> payment

SELECT
    category.name AS genre,
    ROUND(SUM(payment.amount), 2) AS gross_revenue
FROM category
JOIN film_category
    ON category.category_id = film_category.category_id
JOIN inventory
    ON film_category.film_id = inventory.film_id
JOIN rental
    ON inventory.inventory_id = rental.inventory_id
JOIN payment
    ON rental.rental_id = payment.rental_id
GROUP BY
    category.name
ORDER BY
    gross_revenue DESC
LIMIT 5;

-- Question 7: Availability of "Academy Dinosaur" at Store 1
-- Goal: Check whether at least one copy of "Academy Dinosaur" is currently available at Store 1.
-- Tables needed: film, inventory, rental.
-- Relationship path:
-- film -> inventory -> rental

SELECT
    film.title AS title,
    inventory.store_id AS store_id,
    COUNT(inventory.inventory_id) AS available_copies
FROM film
JOIN inventory
    ON film.film_id = inventory.film_id
WHERE film.title = 'ACADEMY DINOSAUR'
  AND inventory.store_id = 1
  AND NOT EXISTS (
      SELECT 1
      FROM rental
      WHERE rental.inventory_id = inventory.inventory_id
        AND rental.return_date IS NULL
  )
GROUP BY
    film.title,
    inventory.store_id;
	
	--Yes, “Academy Dinosaur” is available at Store 1, with 4 available copies.